import{renderScene3D,DEFAULT_CAMERA}from './scene3d.js';
import{native3DFiles}from './export3d.js';
import{renderEffect}from './engine.js';
const enc=new TextEncoder();
export function parseGraph(text){return JSON.parse('['+text.trim().replace(/}\s*\n\s*{/g,'},{')+']');}
const guid=()=>crypto.randomUUID().replaceAll('-','');
export function shaderGraph(template,textureGuid,side,fps){const objects=parseGraph(template),graph=objects[0],find=s=>objects.find(o=>o.m_Type.endsWith(s));
 for(let o of objects){if(o.m_Type.endsWith('UniversalTarget')){o.m_SurfaceType=1;o.m_AlphaMode=0;o.m_RenderFace=0;o.m_ZWriteControl=2;}if(o.m_Type.endsWith('SystemData')){o.m_SurfaceType=1;o.m_BlendMode=0;o.m_ZWrite=false;o.m_DoubleSidedMode=2;}}
 const tex=find('Texture2DShaderProperty');tex.m_Value={m_SerializedTexture:JSON.stringify({texture:{fileID:2800000,guid:textureGuid,type:3}}),m_Guid:textureGuid};graph.m_Path='VFX Forge';
 function slot(type,id,name,output,value=0){const o={m_SGVersion:0,m_Type:'UnityEditor.ShaderGraph.'+type,m_ObjectId:guid(),m_Id:id,m_DisplayName:name,m_SlotType:output?1:0,m_Hidden:false,m_ShaderOutputName:name,m_StageCapability:3,m_Value:value,m_DefaultValue:value,m_Labels:[]};if(type==='UVMaterialSlot')o.m_Channel=0;objects.push(o);return{m_Id:o.m_ObjectId};}
 function node(type,name,x,y,slots,extra={}){const n={m_SGVersion:0,m_Type:'UnityEditor.ShaderGraph.'+type,m_ObjectId:guid(),m_Group:{m_Id:''},m_Name:name,m_DrawState:{m_Expanded:true,m_Position:{serializedVersion:'2',x,y,width:180,height:180}},m_Slots:slots,synonyms:[],m_Precision:0,m_PreviewExpanded:true,m_DismissedVersion:0,m_PreviewMode:0,m_CustomColors:{m_SerializableColors:[]},...extra};objects.push(n);graph.m_Nodes.push({m_Id:n.m_ObjectId});return n;}
 const t=node('TimeNode','Time',-1200,500,[slot('Vector1MaterialSlot',0,'Time',true)]);
 const base=find('MultiplyNode');for(const ref of base.m_Slots){const s=objects.find(o=>o.m_ObjectId===ref.m_Id);if(s.m_Id===1)for(const key of Object.keys(s.m_Value))s.m_Value[key]=1;}const mul=structuredClone(base);mul.m_ObjectId=guid();mul.m_Name='Playback FPS';mul.m_DrawState.m_Position.x=-980;mul.m_DrawState.m_Position.y=500;mul.m_Slots=base.m_Slots.map(r=>{let s=structuredClone(objects.find(o=>o.m_ObjectId===r.m_Id));s.m_ObjectId=guid();if(s.m_Id===1){for(const key of Object.keys(s.m_Value))s.m_Value[key]=fps;s.m_DefaultValue=structuredClone(s.m_Value);}objects.push(s);return{m_Id:s.m_ObjectId};});objects.push(mul);graph.m_Nodes.push({m_Id:mul.m_ObjectId});
 const flip=node('FlipbookNode','Flipbook',-740,500,[slot('UVMaterialSlot',0,'UV',false,{x:0,y:0}),slot('Vector1MaterialSlot',1,'Width',false,side),slot('Vector1MaterialSlot',2,'Height',false,side),slot('Vector1MaterialSlot',3,'Tile',false,0),slot('Vector2MaterialSlot',4,'Out',true,{x:0,y:0})],{m_InvertX:false,m_InvertY:true});
 const sample=find('SampleTexture2DNode');function edge(a,ai,b,bi){graph.m_Edges.push({m_OutputSlot:{m_Node:{m_Id:a.m_ObjectId},m_SlotId:ai},m_InputSlot:{m_Node:{m_Id:b.m_ObjectId},m_SlotId:bi}});}edge(t,0,mul,0);edge(mul,2,flip,3);edge(flip,4,sample,2);return objects.map(o=>JSON.stringify(o,null,4)).join('\n\n');
}
export function vfxGraph(template,textureGuid,side,fps,duration){let text=template.replace(/\r\n/g,'\n');const chunks=text.split(/(?=--- !u!)/);let changed=new Set();for(let i=0;i<chunks.length;i++){let b=chunks[i];const m=b.match(/  m_Property:\n    name: (\w+)/);if(!m)continue;let value;switch(m[1]){case'mainTexture':value=`'{"obj":{"fileID":2800000,"guid":"${textureGuid}","type":3}}'`;break;case'flipBookSize':value=`'{"x":${side},"y":${side}}'`;break;case'cycles':value='1';break;case'Rate':value=String(1/duration);break;case'_Lifetime':value=String(duration);break;case'_Size':value='2';break;case'_Velocity':value=`'{"vector":{"x":0.0,"y":0.0,"z":0.0}}'`;break;}if(value!==undefined){b=b.replace(/m_SerializableObject: [^\n]*/,`m_SerializableObject: ${value}`);changed.add(m[1]);}chunks[i]=b;}for(let key of['mainTexture','flipBookSize','cycles','_Lifetime','_Size','_Velocity','Rate'])if(!changed.has(key))throw Error('Unity VFX template ไม่ครบ: '+key);return chunks.join('').replaceAll('025_FlipbookPlayerFullLoop','VFXForgeFlipbook');}
export function textureMeta(id,size){return `fileFormatVersion: 2\nguid: ${id}\nTextureImporter:\n  serializedVersion: 12\n  mipmaps:\n    mipMapMode: 0\n    enableMipMap: 0\n    sRGBTexture: 1\n  isReadable: 0\n  textureSettings:\n    serializedVersion: 2\n    filterMode: 1\n    aniso: 1\n    mipBias: 0\n    wrapU: 1\n    wrapV: 1\n    wrapW: 1\n  nPOTScale: 0\n  maxTextureSize: ${Math.max(2048,size)}\n  textureFormat: 1\n  textureCompression: 0\n  alphaUsage: 1\n  alphaIsTransparency: 1\n  textureType: 0\n  textureShape: 1\n  platformSettings:\n  - serializedVersion: 3\n    buildTarget: DefaultTexturePlatform\n    maxTextureSize: ${Math.max(2048,size)}\n    resizeAlgorithm: 0\n    textureFormat: -1\n    textureCompression: 0\n    compressionQuality: 100\n    overridden: 0\n  userData: VFXForge\n  assetBundleName:\n  assetBundleVariant:\n`;}
export function crc32(data){let crc=0xffffffff;for(const byte of data){crc^=byte;for(let i=0;i<8;i++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}return(crc^0xffffffff)>>>0;}
export async function zipFiles(files){const chunks=[],central=[];let offset=0;for(const[name,content]of files){const data=typeof content==='string'?enc.encode(content):content instanceof Blob?new Uint8Array(await content.arrayBuffer()):content,n=enc.encode(name),crc=crc32(data),local=new Uint8Array(30+n.length),v=new DataView(local.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint16(12,33,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,n.length,true);local.set(n,30);const ce=new Uint8Array(46+n.length),c=new DataView(ce.buffer);c.setUint32(0,0x02014b50,true);c.setUint16(4,20,true);c.setUint16(6,20,true);c.setUint16(8,0x800,true);c.setUint16(14,33,true);c.setUint32(16,crc,true);c.setUint32(20,data.length,true);c.setUint32(24,data.length,true);c.setUint16(28,n.length,true);c.setUint32(42,offset,true);ce.set(n,46);chunks.push(local,data);central.push(ce);offset+=local.length+data.length;}const len=central.reduce((s,c)=>s+c.length,0),end=new Uint8Array(22),e=new DataView(end.buffer);e.setUint32(0,0x06054b50,true);e.setUint16(8,files.length,true);e.setUint16(10,files.length,true);e.setUint32(12,len,true);e.setUint32(16,offset,true);return new Blob([...chunks,...central,end],{type:'application/zip'});}
const png=canvas=>new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('สร้าง PNG ไม่ได้')),'image/png'));
function bakeFrame(canvas,project,time,camera){if(project.mode==='3d')renderScene3D(canvas.getContext('2d'),project.layers,time,{camera:camera||project.camera||DEFAULT_CAMERA,width:canvas.width,height:canvas.height,clear:true});else renderEffect(canvas,project.layers,time,project.duration);}
export async function exportEffect(project,{format,resolution,frames,time,camera,name,onProgress=()=>{}}){if(format==='3d'){if(project.mode!=='3d')throw Error('เลือกโหมด 3D ก่อนส่งออก');return{blob:await zipFiles(await native3DFiles(project,frames,name,onProgress)),name:name+'_world3d.zip'};}if(!['png','sheet','shader','vfx'].includes(format))throw Error('รูปแบบไม่ถูกต้อง');const canvas=document.createElement('canvas');canvas.width=canvas.height=resolution;if(format==='png'){bakeFrame(canvas,project,time,camera);return{blob:await png(canvas),name:name+'.png'};}
const side=Math.sqrt(frames),size=resolution*side;if(size>8192)throw Error('Atlas ใหญ่เกิน 8192 px');const atlas=document.createElement('canvas');atlas.width=atlas.height=size;const c=atlas.getContext('2d');if(!c)throw Error('หน่วยความจำไม่พอ');for(let i=0;i<frames;i++){bakeFrame(canvas,project,i/frames*project.duration,camera);c.drawImage(canvas,i%side*resolution,Math.floor(i/side)*resolution);onProgress(`Bake frame ${i+1} / ${frames}`);if(i%4===0)await new Promise(r=>setTimeout(r,0));}
const textureGuid=guid(),fps=frames/project.duration,atlasName=name+'_atlas.png',meta={mode:project.mode||'2d',camera:project.mode==='3d'?(camera||project.camera||DEFAULT_CAMERA):null,generator:'VFX Forge 1.1',name:project.name,texture:atlasName,width:size,height:size,frameWidth:resolution,frameHeight:resolution,columns:side,rows:side,frameCount:frames,duration:project.duration,fps,order:'left-to-right, top-to-bottom',loop:true,frames:Array.from({length:frames},(_,i)=>({index:i,x:i%side*resolution,y:Math.floor(i/side)*resolution,w:resolution,h:resolution,time:i/fps}))};let files=[[atlasName,await png(atlas)],[atlasName+'.meta',textureMeta(textureGuid,size)],[name+'.sheet.json',JSON.stringify(meta,null,2)],[name+'.vfxforge.json',JSON.stringify(project,null,2)]];
const licenseResponse=await fetch('UNITY-COMPANION-LICENSE.txt');if(!licenseResponse.ok)throw Error('โหลด license ไม่ได้');files.push(['UNITY-COMPANION-LICENSE.txt',await licenseResponse.text()]);
if(format==='shader'||format==='vfx'){let r=await fetch(format==='shader'?'template.shadergraph':'template.vfx');if(!r.ok)throw Error('โหลดเทมเพลต Graph ไม่ได้');let template=await r.text();files.push([name+(format==='shader'?'.shadergraph':'.vfx'),format==='shader'?shaderGraph(template,textureGuid,side,fps):vfxGraph(template,textureGuid,side,fps,project.duration)]);}
files.push(['README.md',`# ${project.name}\n\nExported by VFX Forge.\n\n## Import into Unity\n\nTarget: Unity 6 with Shader Graph / Visual Effect Graph 17.x. Import compatibility has NOT been verified in the Unity Editor.\n\n1. Extract the ENTIRE ZIP into a new folder under Assets. Keep PNG and its .meta together so texture references resolve. Use a fresh folder for each export to avoid duplicate GUIDs.\n2. Shader Graph: create a Material using the exported shadergraph, assign it to a Quad. Time -> Multiply (${fps} FPS) -> Flipbook (${side} x ${side}) animates the baked texture. Transparent alpha blending, two-sided.\n3. VFX Graph: assign the .vfx to a Visual Effect component. It uses Unity's Full Loop flipbook test template with atlas, grid and frame rate replaced. Its emission and particle controls can be edited in Unity.\n4. For particle systems: set Texture Sheet Animation to ${side} x ${side} tiles, ${project.duration} second lifetime, one cycle.\n\n## Content\n\n${frames} frames, ${resolution}px per frame, ${size}px atlas, ${fps} FPS, ${project.duration}s loop. Row-major order from TOP LEFT.\n\nBaked 2D flipbook on a quad; no editable procedural effect nodes or volumetric geometry are exported. Layers, timing, and colors are baked into pixels. Preview grid, background and zoom are excluded.\n\nGraph templates adapted from Unity-Technologies/Graphics (master), Unity Companion License. See THIRD-PARTY-NOTICES.txt.\n`],['THIRD-PARTY-NOTICES.txt',await(await fetch('THIRD-PARTY-NOTICES.txt')).text()]);onProgress('กำลังจัดแพ็กเกจ…');return{blob:await zipFiles(files),name:name+'_'+format+'.zip'};}
